window.addEventListener('message',event=>{
 if(event.origin!==location.origin||event.source!==window.parent||event.data?.type!=='robisie-pack-navigate')return;
 let url;try{url=new URL(event.data.url);}catch{return;}
 if(url.origin!==location.origin||!['/app/robisie/','/app/robisie/index.html'].includes(url.pathname))return;
 void (async()=>{try{if($('#dialog')?.open){toast('Zamknij otwarte okno, aby przejść do innej faktury.');return;}await flushChanges({normalize:false});history.replaceState(null,'',url.pathname+url.search+url.hash);const rows=await API.projects();all=rows.map(row=>({...row,payload:C.captureCatalog(config.payload,row.payload)}));await openRequestedPurchase();}catch(error){toast(error.message);}})();
});
